namespace zeroerr {

template <class T1, class... T>
struct last {
    using type = typename last<T...>::type;
};

template <class T1>
struct last<T1> {
    using type = T1;
};

/**
 * @brief get_last is a function to get the last argument of a variadic template.
 *        It is used by DebugExpr.
 */
template <typename... Args>
auto get_last(Args&&... args) -> typename last<Args...>::type {
    return std::get<sizeof...(Args) - 1>(std::tie(args...));
}


/**
 * @brief DebugExpr is a function to print any type of variable with its type name.
 *        It is used by dbg macro.
 */
template <typename... T>
auto DebugExpr(const char* file, unsigned line, const char* func, const char* exprs, T... t) ->
    typename last<T...>::type {
    zeroerr::String fileName(file);
    auto        p = fileName.find_last_of('/');
    if (p != zeroerr::String::npos) fileName = fileName.substr(p + 1);

    getStderrPrinter().os << Dim << "[" << fileName << ":" << line << " " << func << "] " << Reset;
    getStderrPrinter().os << FgCyan << exprs << Reset << " = ";
    Printer print(getStderrPrinter().os);
    print.line_break = "";
    print(t...);
    getStderrPrinter().os << " (" << FgGreen;
    zeroerr::String typenames[] = {print.type(t)...};
    for (unsigned i = 0; i < sizeof...(T); ++i) {
        if (i != 0) getStderrPrinter().os << ", ";
        getStderrPrinter().os << typenames[i];
    }
    getStderrPrinter().os << Reset << ")" << '\n';
    return get_last(t...);
}


}  // namespace zeroerr

